const featuredActivities=[
{id:'um-objeto',title:'Um objeto, uma história',category:'quebrar-gelo',label:'Quebra-gelo',time:'10 min',people:'4–16 pessoas',desc:'Cada pessoa escolhe um objeto que trouxe e conta uma história breve ligada a ele.',steps:['Peça que todos procurem um objeto que estejam usando ou tenham na bolsa.','Dê um minuto para cada pessoa compartilhar por que o escolheu.','Feche perguntando: “O que essa história revela sobre você?”'],tip:'Você pode começar, modelando uma resposta honesta e curta.'},
{id:'linha-tempo',title:'Linha do tempo',category:'conexao',label:'Conexão',time:'20 min',people:'5–20 pessoas',desc:'Uma caminhada pelas memórias que nos formaram — e pelas pessoas que estiveram ali.',steps:['Marque no chão uma linha imaginária: infância, adolescência e hoje.','Leia perguntas simples e convide as pessoas a se posicionarem na fase correspondente.','Em cada rodada, deixe duas ou três pessoas compartilharem um pouco.'],tip:'Evite pressionar. Participar em silêncio também é participar.'},
{id:'versiculo-vivo',title:'Versículo vivo',category:'biblica',label:'Bíblica',time:'15 min',people:'3–15 pessoas',desc:'Uma forma criativa de guardar a Palavra e descobrir o que ela fala a cada pessoa.',steps:['Escolha um versículo curto ligado ao tema do encontro.','Distribua as palavras do texto entre as pessoas.','Cada um lê sua palavra e compartilha uma aplicação para a semana.'],tip:'Use um versículo que já apareça na conversa da noite.'},
{id:'duas-verdades',title:'Duas verdades e um sonho',category:'divertida',label:'Divertida',time:'12 min',people:'4–18 pessoas',desc:'Descubra fatos surpreendentes e desejos ainda escondidos de quem está ao seu lado.',steps:['Cada pessoa pensa em duas verdades sobre si e em um sonho que tem.','Ela compartilha as três frases sem revelar qual é o sonho.','O grupo tenta adivinhar e, depois, faz uma pergunta curiosa sobre o sonho.'],tip:'Dê o tom: sonhos simples e grandes têm o mesmo valor.'},
{id:'nome-que-fica',title:'Nome que fica',category:'conexao',label:'Conexão',time:'8 min',people:'3–12 pessoas',desc:'Uma dinâmica breve para aprender nomes e perceber detalhes que aproximam.',steps:['Em círculo, a primeira pessoa diz seu nome e algo pelo qual é grata hoje.','A pessoa seguinte repete o anterior e acrescenta o próprio.','Continue até todos falarem. Celebrem quem lembrar toda a sequência.'],tip:'Funciona especialmente bem quando há gente nova na célula.'},
{id:'caixa-de-perguntas',title:'Caixa de perguntas',category:'quebrar-gelo',label:'Quebra-gelo',time:'15 min',people:'4–20 pessoas',desc:'Perguntas leves que fazem a conversa começar sem exigir exposição demais.',steps:['Escreva perguntas em pequenos papéis e coloque em uma caixa.','Cada participante tira uma pergunta e responde no próprio ritmo.','Quem quiser pode comentar, mas a regra é: ninguém precisa aconselhar.'],tip:'Misture perguntas engraçadas com perguntas afetivas para criar ritmo.'},
{id:'mapa-da-graca',title:'Mapa da graça',category:'biblica',label:'Bíblica',time:'18 min',people:'4–14 pessoas',desc:'Perceba os lugares onde Deus já esteve presente na caminhada de cada um.',steps:['Entregue uma folha e peça para desenharem uma estrada simples.','Marquem três momentos em que sentiram cuidado, provisão ou recomeço.','Compartilhem um dos pontos e orem em gratidão ao final.'],tip:'Deixe papel e canetas coloridas visíveis: pequenos gestos convidam à participação.'},
{id:'desafio-sem-palavras',title:'Desafio sem palavras',category:'divertida',label:'Divertida',time:'10 min',people:'6–20 pessoas',desc:'Risos garantidos em uma competição de mímica feita em pequenos grupos.',steps:['Divida o grupo em duas equipes.','Prepare temas simples: filmes, histórias bíblicas, profissões ou lugares.','Cada rodada dura um minuto; vence quem somar mais acertos.'],tip:'Mantenha temas inclusivos — a graça é rir junto, não deixar alguém de fora.'}];
const categoryMap={Integração:['quebrar-gelo','Integração'],Movimento:['divertida','Movimento'],Riso:['divertida','Riso'],Bíblia:['biblica','Bíblica'],Oração:['biblica','Oração'],Comunhão:['conexao','Comunhão'],Visitantes:['quebrar-gelo','Visitantes'],Profundo:['conexao','Profundo']};
const importedActivities=(window.mtrDynamicsCatalog||[]).map(d=>{const [category,label]=categoryMap[d.cat]||['conexao',d.cat];return{id:'mtr-'+d.id,title:d.title,category,label,time:d.time,people:d.participants,desc:d.obj,steps:[d.how,d.transition,d.spiritual],tip:d.tip}});
const activities=[...featuredActivities,...importedActivities];
const icons={home:'<path d="M3 10.6 12 3l9 7.6v9.1a1.3 1.3 0 0 1-1.3 1.3H4.3A1.3 1.3 0 0 1 3 19.7z"/><path d="M9 21v-6h6v6"/>',spark:'<path d="m12 2 1.7 6.3L20 10l-6.3 1.7L12 18l-1.7-6.3L4 10l6.3-1.7z"/>',book:'<path d="M4 4.8A2.8 2.8 0 0 1 6.8 2H20v17H6.8A2.8 2.8 0 0 0 4 21.8z"/><path d="M4 4.8V22"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3.5 21v-1.5A4.5 4.5 0 0 1 8 15h2a4.5 4.5 0 0 1 4.5 4.5V21"/><path d="M16 5.2a3 3 0 0 1 0 5.6M18.5 15.4a4.5 4.5 0 0 1 2 3.8V21"/>',heart:'<path d="M20.8 8.7c0 5-8.8 10.3-8.8 10.3S3.2 13.7 3.2 8.7A4.6 4.6 0 0 1 12 6.9a4.6 4.6 0 0 1 8.8 1.8Z"/>',play:'<path d="m9 5 9 7-9 7z"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',shuffle:'<path d="M16 3h5v5M4 20 21 3M21 16v5h-5M15 15l6 6M4 4l5 5"/>',search:'<circle cx="10.7" cy="10.7" r="6.2"/><path d="m16 16 4.3 4.3"/>',clock:'<circle cx="12" cy="12" r="8.5"/><path d="M12 7v5l3.5 2"/>',users:'<circle cx="8.5" cy="8" r="2.6"/><path d="M3.5 19v-1a4 4 0 0 1 4-4h2a4 4 0 0 1 4 4v1"/><path d="M16 6a2.6 2.6 0 0 1 0 5M17.7 14.5a4 4 0 0 1 2.7 3.8v.7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]}</svg>`;document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const dailyPool=window.dailyCellVerses||[];
if(dailyPool.length){const today=new Date(),todayStart=new Date(today.getFullYear(),today.getMonth(),today.getDate()),anchor=new Date(2026,0,1),dayIndex=Math.floor((todayStart-anchor)/86400000),daily=dailyPool[((dayIndex%dailyPool.length)+dailyPool.length)%dailyPool.length];document.querySelector('#dailyLabel').textContent=`VERSÍCULO DO DIA`;document.querySelector('#dailyReference').textContent=daily.ref;document.querySelector('#meeting-title').textContent=daily.theme;document.querySelector('#dailyVerse').textContent=daily.text;document.querySelector('#dailyPrompt').textContent=`Palavra da célula: ${daily.prompt}`}
let activeFilter='all',favorites=new Set(JSON.parse(localStorage.getItem('cell-favorites')||'[]')),selected=null,timerId=null,seconds=0,currentPage=1;const PAGE_SIZE=6;
const grid=document.querySelector('#activityGrid'),count=document.querySelector('#activityCount'),favCount=document.querySelector('#favoriteCount'),search=document.querySelector('#searchInput'),detail=document.querySelector('#detailContent'),panel=document.querySelector('#detailPanel'),backdrop=document.querySelector('#detailBackdrop');
const duration=a=>parseInt(a.time,10)*60,format=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;
function list(){const q=search.value.toLowerCase().trim();return activities.filter(a=>(activeFilter==='all'||a.category===activeFilter)&&`${a.title} ${a.label} ${a.desc}`.toLowerCase().includes(q))}
function card(a){return `<article class="activity-card ${selected?.id===a.id?'selected':''}"><div class="card-top"><span class="tag ${a.category}">${a.label}</span><button class="favorite ${favorites.has(a.id)?'selected':''}" data-favorite="${a.id}" aria-label="${favorites.has(a.id)?'Remover':'Salvar'} ${a.title}">${icon('heart')}</button></div><h3>${a.title}</h3><p>${a.desc}</p><div class="card-bottom"><div class="meta"><span>${icon('clock')}${a.time}</span><span>${icon('users')}${a.people}</span></div><button class="open-card" data-open="${a.id}">abrir ${icon('arrow')}</button></div></article>`}
function render(){const values=list();const totalPages=Math.max(1,Math.ceil(values.length/PAGE_SIZE));if(currentPage>totalPages) currentPage=totalPages;const pageItems=values.slice((currentPage-1)*PAGE_SIZE, currentPage*PAGE_SIZE);count.textContent=`${values.length} ${values.length===1?'dinâmica disponível':'dinâmicas disponíveis'}${values.length>PAGE_SIZE?` · página ${currentPage} de ${totalPages}`:''}`;favCount.textContent=favorites.size;let html=pageItems.length?pageItems.map(card).join(''):'<p class="empty">Não encontrei uma dinâmica com esse termo. Tente outra palavra.</p>';if(values.length>PAGE_SIZE){html+=renderPagination(totalPages);}grid.innerHTML=html}
function renderPagination(total){let h='<nav class="pagination" aria-label="Paginação">';h+=`<button class="page-btn" data-page="${currentPage-1}" ${currentPage===1?'disabled':''} aria-label="Anterior">‹</button>`;const win=5;let s=Math.max(1,currentPage-Math.floor(win/2)),e=Math.min(total,s+win-1);if(e-s+1<win) s=Math.max(1,e-win+1);for(let i=s;i<=e;i++) h+=`<button class="page-btn ${i===currentPage?'active':''}" data-page="${i}" ${i===currentPage?'aria-current="page"':''}>${i}</button>`;h+=`<button class="page-btn" data-page="${currentPage+1}" ${currentPage===total?'disabled':''} aria-label="Próxima">›</button>`;h+='</nav>';return h}
function renderDetail(a){if(!a){detail.innerHTML=`<div class="detail-empty"><div><span class="detail-placeholder">${icon('spark')}</span><strong>Escolha uma dinâmica</strong><br /><span>Os passos e o cronômetro aparecem aqui.</span></div></div>`;return}seconds=duration(a);clearInterval(timerId);timerId=null;detail.innerHTML=`<div class="detail-top"><span class="detail-type">${a.label.toUpperCase()}</span><button class="close-detail" id="closeDetail" aria-label="Fechar detalhes">${icon('close')}</button></div><h2 class="detail-title">${a.title}</h2><p class="detail-description">${a.desc}</p><div class="detail-meta"><span>${icon('clock')}${a.time}</span><span>${icon('users')}${a.people}</span></div><p class="steps-title">COMO CONDUZIR</p><ol class="steps">${a.steps.map((s,i)=>`<li class="step"><span class="step-number">${i+1}</span><span>${s}</span></li>`).join('')}</ol><div class="timer"><small>CRONÔMETRO</small><div class="timer-main"><span class="timer-value" id="timerValue">${format(seconds)}</span><div class="timer-controls"><button id="startTimer">Iniciar</button><button id="resetTimer">Reiniciar</button></div></div></div><p class="leader-note"><strong>Dica de líder:</strong> ${a.tip}</p>`}
function select(id){selected=activities.find(a=>a.id===id);render();renderDetail(selected);panel.classList.add('open');backdrop.classList.add('show')}
function toggle(id){favorites.has(id)?favorites.delete(id):favorites.add(id);localStorage.setItem('cell-favorites',JSON.stringify([...favorites]));render()}
function close(){panel.classList.remove('open');backdrop.classList.remove('show')}
function start(){const b=document.querySelector('#startTimer');if(timerId){clearInterval(timerId);timerId=null;b.textContent='Continuar';return}b.textContent='Pausar';timerId=setInterval(()=>{if(seconds<=0){clearInterval(timerId);timerId=null;b.textContent='Concluído';return}seconds--;document.querySelector('#timerValue').textContent=format(seconds)},1000)}
document.querySelector('.filter-scroll').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;activeFilter=b.dataset.filter;currentPage=1;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));render()});grid.addEventListener('click',e=>{const pg=e.target.closest('[data-page]');if(pg && !pg.disabled){const p=parseInt(pg.dataset.page,10);if(p>=1){currentPage=p;render();document.querySelector('#dinamicas').scrollIntoView({behavior:'smooth',block:'start'});return}}const f=e.target.closest('[data-favorite]'),o=e.target.closest('[data-open]');if(f)toggle(f.dataset.favorite);if(o)select(o.dataset.open)});detail.addEventListener('click',e=>{if(e.target.closest('#closeDetail'))close();if(e.target.closest('#startTimer'))start();if(e.target.closest('#resetTimer')){clearInterval(timerId);timerId=null;seconds=duration(selected);document.querySelector('#timerValue').textContent=format(seconds);document.querySelector('#startTimer').textContent='Iniciar'}});backdrop.addEventListener('click',close);search.addEventListener('input',()=>{currentPage=1;render()});
const scrollLibrary=()=>document.querySelector('#dinamicas').scrollIntoView({behavior:'smooth'});document.querySelector('#prepareButton')?.addEventListener('click',scrollLibrary);document.querySelector('#showAllButton').addEventListener('click',()=>{activeFilter='all';search.value='';currentPage=1;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x.dataset.filter==='all'));render();scrollLibrary()});function random(){select(activities[Math.floor(Math.random()*activities.length)].id);scrollLibrary()}document.querySelector('#randomButton')?.addEventListener('click',random);document.querySelector('#quickRandom')?.addEventListener('click',random);
document.querySelector('#focusModeButton')?.addEventListener('click',e=>{document.body.classList.toggle('focus-mode');e.currentTarget.querySelector('span:last-child').textContent=document.body.classList.contains('focus-mode')?'Sair do modo encontro':'Modo encontro'});document.querySelector('#favoritesButton')?.addEventListener('click',()=>{search.value='';activeFilter='all';const saved=activities.filter(a=>favorites.has(a.id));count.textContent=`${saved.length} ${saved.length===1?'dinâmica salva':'dinâmicas salvas'}`;grid.innerHTML=saved.length?saved.map(card).join(''):'<p class="empty">Você ainda não salvou nenhuma dinâmica. Use o coração para guardar uma ideia.</p>';scrollLibrary()});document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.nav;if(key==='dinamicas')scrollLibrary();else if(key==='inicio')document.querySelector('#inicio').scrollIntoView({behavior:'smooth'});document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x===b))}));
render();renderDetail(null);
function renderDetail(a){if(!a){detail.innerHTML=`<div class="detail-empty"><div><span class="detail-placeholder">${icon('spark')}</span><strong>Escolha uma dinâmica</strong><br /><span>Os passos e o cronômetro aparecem aqui.</span></div></div>`;return}const source=a.id.startsWith('mtr-')?(window.mtrDynamicsCatalog||[]).find(item=>`mtr-${item.id}`===a.id):null;seconds=duration(a);clearInterval(timerId);timerId=null;detail.innerHTML=`<div class="detail-top"><span class="detail-type">${a.label.toUpperCase()}</span><button class="close-detail" id="closeDetail" aria-label="Fechar detalhes">${icon('close')}</button></div><h2 class="detail-title">${a.title}</h2><p class="detail-description">${a.desc}</p>${source?.verse?`<section class="detail-source"><small>VERSÍCULO-CHAVE</small><p>${source.verse}</p></section>`:''}<div class="detail-meta"><span>${icon('clock')}${a.time}</span><span>${icon('users')}${a.people}</span></div>${source?.mat?`<section class="detail-extra"><div><small>MATERIAIS</small><p>${source.mat}</p></div><div><small>ENERGIA</small><p>${source.energy||'—'} · ${source.depth||'—'}</p></div></section>`:''}${source?.bestFor?.length?`<div class="detail-tags">${source.bestFor.map(item=>`<span>${item}</span>`).join('')}</div>`:''}<p class="steps-title">COMO CONDUZIR</p><ol class="steps">${a.steps.map((s,i)=>`<li class="step"><span class="step-number">${i+1}</span><span>${s}</span></li>`).join('')}</ol><div class="timer"><small>CRONÔMETRO</small><div class="timer-main"><span class="timer-value" id="timerValue">${format(seconds)}</span><div class="timer-controls"><button id="startTimer">Iniciar</button><button id="resetTimer">Reiniciar</button></div></div></div><p class="leader-note"><strong>Dica de líder:</strong> ${a.tip}</p>${source?.avoidIf?`<p class="leader-note avoid-note"><strong>Quando evitar:</strong> ${source.avoidIf}</p>`:''}`}
